import { resolvePropertyPath } from '@threlte/core';
export const haveProperty = (objects, property) => {
    return objects.every((object) => property in object);
};
export const areOfType = (objects, isType) => {
    return objects.every((object) => isType in object);
};
export const readFromFirstObject = (objects, propertyPath) => {
    const { target, key } = resolvePropertyPath(objects[0], propertyPath);
    return target[key];
};
export const areCamera = (objects) => {
    return (areOfType(objects, 'isPerspectiveCamera') ||
        areOfType(objects, 'isOrthographicCamera'));
};
export const mutualType = (objects) => {
    const types = objects.map((object) => object.type);
    const uniqueTypes = new Set(types);
    if (uniqueTypes.size === 1 && types[0]) {
        return `(${types[0]})`;
    }
    return undefined;
};
export const areLight = (objects) => {
    return (areOfType(objects, 'isDirectionalLight') ||
        areOfType(objects, 'isPointLight') ||
        areOfType(objects, 'isSpotLight') ||
        areOfType(objects, 'isHemisphereLight') ||
        areOfType(objects, 'isRectAreaLight') ||
        areOfType(objects, 'isAmbientLight'));
};
export const haveMaterialProperty = (objects) => {
    return haveProperty(objects, 'material');
};
